# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: render
def render(xs):
    return [v * v for v in xs]

# region: sift
def sift(xs, factor=3):
    return [v * factor for v in xs]

# region: gather
def gather(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: emit
def emit(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(intake(gather(sift(render(fold(raw))))))

